subjectTypes.subjectSummaryRule:
'use strict';
({params, imports}) => {
    const individual = params.individual;
    const moment = imports.moment;
    const _ = imports.lodash;
    const summaries = [];
    const CONCEPT_TRAINING_COURSE_UUID = "6c7a2151-ffcf-53cb-8ad2-b335084218ee";
    const CONCEPT_EDUCATION_PROGRAM_UUID = "86d7b5a9-46db-579e-bdee-c4ab04e32ea8";

    const done = individual.getEncounters(true).filter(enc => enc.encounterDateTime);
    const planned = individual.getEncounters(true).filter(enc => !enc.encounterDateTime && enc.earliestVisitDateTime);
    const lastEvent = _.maxBy(done.filter(enc => ['Livelihood Event', 'Education Event'].includes(enc.encounterType.name)), enc => enc.encounterDateTime);
    const lastVisit = _.maxBy(done, enc => enc.encounterDateTime);
    const nextVisit = _.minBy(planned, enc => enc.earliestVisitDateTime);

    // the camp slip's facts, so a worker can tell the person without a printout (13 Nov)
    const CONCEPT_CAMP_TYPE_UUID = "6c212c05-3ce5-5c0b-8ac2-8fd70dfbd44a";
    const lastCamp = _.maxBy(done.filter(enc => enc.encounterType.name == 'Health Camp'), enc => enc.encounterDateTime);
    const nextFollowUp = _.minBy(planned.filter(enc => enc.encounterType.name.indexOf('Follow-up') > 0), enc => enc.earliestVisitDateTime);

    if (lastEvent) {
        const programme = lastEvent.getObservationReadableValue(CONCEPT_TRAINING_COURSE_UUID) || lastEvent.getObservationReadableValue(CONCEPT_EDUCATION_PROGRAM_UUID);
        summaries.push({name: 'Latest programme', value: programme + ' (' + moment(lastEvent.encounterDateTime).format('DD-MM-YYYY') + ')'});
    }
    if (lastVisit) {
        summaries.push({name: 'Last visit', value: lastVisit.encounterType.name + ', ' + moment(lastVisit.encounterDateTime).format('DD-MM-YYYY')});
    }
    if (nextVisit) {
        summaries.push({name: 'Next planned visit', value: nextVisit.encounterType.name + ', ' + moment(nextVisit.earliestVisitDateTime).format('DD-MM-YYYY')});
    }
    if (lastCamp) {
        summaries.push({name: 'Last camp', value: (lastCamp.getObservationReadableValue(CONCEPT_CAMP_TYPE_UUID) || 'Health Camp') + ', ' + moment(lastCamp.encounterDateTime).format('DD-MM-YYYY')});
    }
    if (nextFollowUp) {
        summaries.push({name: 'Next follow-up', value: nextFollowUp.encounterType.name + ', ' + moment(nextFollowUp.earliestVisitDateTime).format('DD-MM-YYYY')});
    }

    return summaries;
};

'use strict';
({params, imports}) => {
    const batch = params.individual;
    const moment = imports.moment;
    const _ = imports.lodash;
    const db = params.db;
    const summaries = [];
    const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";
    const CONCEPT_BATCH_LAST_CLASS_DAY_UUID = "476c6430-95f7-5efa-8a34-8cedf9011e3b";
    const BATCH_DAYS = {
        "Summer Camp": 5,
        "Beautician Skill Training": 90,
        "Career Guidance and Development Program": 15,
        "CSL (STEM Lab)": 365,
        "Sewing (SST)": 90,
        "Computer (CST)": 90,
        "EV (TST-EV)": 90,
        "Solar (TST-Solar)": 90,
        "Candle and Diya (CMT)": 5,
        "Chocolate (CMT)": 3,
        "Jewellery (JMT)": 5,
        "Financial (FLP)": 5,
        "Entrepreneurship (EDT)": 10,
        "Asani (ADT)": 1
    };
    const startDay = batch => moment(batch.getObservationValue(CONCEPT_BATCH_START_DATE_UUID) || batch.registrationDate).startOf('day');
    // class days run Monday to Saturday, so a course of N days ends N class days after the start, Sundays skipped
    const lastClassDay = batch => {
        const own = batch.getObservationValue(CONCEPT_BATCH_LAST_CLASS_DAY_UUID);
        if (own) return moment(own).startOf('day');
        const days = BATCH_DAYS[batch.subjectType.name] || 30;
        const start = startDay(batch);
        const mondayFirst = (start.day() + 6) % 7;
        return start.clone().add(days - 1 + Math.floor((mondayFirst + days - 1) / 6), 'days');
    };

    // each student's marks at held classes; the app marks only students on the roster that day
    let held = 0;
    const marks = {};
    if (db.isSqlite) {
        held = db.execCount("SELECT COUNT(*) FROM session WHERE +voided = 0 AND status = 'Held' AND group_subject_uuid = ?", [batch.uuid]);
        db.execQuery("SELECT r.subject_uuid AS person, COUNT(*) AS counted, SUM(CASE WHEN r.status = 'Present' THEN 1 ELSE 0 END) AS present"
            + " FROM attendance_record r JOIN session s ON s.uuid = r.session_uuid WHERE +r.voided = 0 AND +s.voided = 0 AND s.status = 'Held'"
            + ' AND s.group_subject_uuid = ? GROUP BY 1', [batch.uuid]).forEach(m => { marks[m.person] = m; });
    } else {
        const sessions = db.objects('Session').filtered("voided = false AND status = 'Held' AND groupSubjectUUID = $0", batch.uuid);
        held = sessions.length;
        sessions.forEach(s => db.objects('AttendanceRecord').filtered('voided = false AND sessionUUID = $0', s.uuid).forEach(r => {
            const m = marks[r.subjectUUID] || (marks[r.subjectUUID] = {counted: 0, present: 0});
            m.counted += 1;
            if (r.status == 'Present') { m.present += 1; }
        }));
    }
    summaries.push({name: 'Sessions held', value: held});
    summaries.push({name: 'Last class day', value: lastClassDay(batch).format('DD-MM-YYYY')});
    if (held >= 4) {
        const isLow = m => !!m && m.counted >= 4 && m.present / m.counted < 0.75;
        const low = _.filter(batch.groupSubjects, g => !g.voided && !g.membershipEndDate && isLow(marks[g.memberSubject.uuid]));
        summaries.push({name: 'Below 75% attendance', value: low.length ? low.map(g => g.memberSubject.nameString).join(', ') : 'None'});
    }

    return summaries;
};

subjectTypes.memberAdditionEligibilityCheckRule:
"use strict";
({params, imports}) => {
    const member = params.member;
    const group = params.group;
    const moment = imports.moment;
    const CONCEPT_CONSENT_GIVEN_UUID = "c11b4e33-565c-58e6-8324-0c4d30da2522";
    const CONCEPT_NO_UUID = "fa43440e-cedd-503c-881b-c37d2100f00f";

    const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";
    const CONCEPT_BATCH_LAST_CLASS_DAY_UUID = "476c6430-95f7-5efa-8a34-8cedf9011e3b";
    const BATCH_DAYS = {
        "Summer Camp": 5,
        "Beautician Skill Training": 90,
        "Career Guidance and Development Program": 15,
        "CSL (STEM Lab)": 365,
        "Sewing (SST)": 90,
        "Computer (CST)": 90,
        "EV (TST-EV)": 90,
        "Solar (TST-Solar)": 90,
        "Candle and Diya (CMT)": 5,
        "Chocolate (CMT)": 3,
        "Jewellery (JMT)": 5,
        "Financial (FLP)": 5,
        "Entrepreneurship (EDT)": 10,
        "Asani (ADT)": 1
    };
    const startDay = batch => moment(batch.getObservationValue(CONCEPT_BATCH_START_DATE_UUID) || batch.registrationDate).startOf('day');
    // class days run Monday to Saturday, so a course of N days ends N class days after the start, Sundays skipped
    const lastClassDay = batch => {
        const own = batch.getObservationValue(CONCEPT_BATCH_LAST_CLASS_DAY_UUID);
        if (own) return moment(own).startOf('day');
        const days = BATCH_DAYS[batch.subjectType.name] || 30;
        const start = startDay(batch);
        const mondayFirst = (start.day() + 6) % 7;
        return start.clone().add(days - 1 + Math.floor((mondayFirst + days - 1) / 6), 'days');
    };

    // a batch that has ended takes no new students. The app runs this before the join date is entered,
    // so it checks today; Data quality catches a join date after the end, from any route
    const end = lastClassDay(group);
    if (moment().isAfter(end.clone().add(3, 'days'), 'day')) {
        return {
            eligible: {
                value: false,
                message: "This batch ended on " + end.format("DD-MM-YYYY") + ". Add the student to a current batch"
            }
        };
    }

    if (member.getObservationValue(CONCEPT_CONSENT_GIVEN_UUID) == CONCEPT_NO_UUID) {
        return {
            eligible: {
                value: false,
                message: "This person did not give consent, so they cannot join a batch"
            }
        };
    }

    return {
        eligible: {
            value: true
        }
    };
};

