        return start.clone().add(days - 1 + Math.floor((mondayFirst + days - 1) / 6), 'days');
    };
    const isCurrent = batch => !today.isAfter(lastClassDay(batch).clone().add(GRACE_DAYS, 'days'), 'day');
    const dayStr = d => moment(d).format('YYYY-MM-DD');
    const TODAY = dayStr(today);
    const isClassDay = today.day() != 0;
    // the last 3 class days before today; Sunday is off
    const RECENT_DAYS = [];
    for (let d = today.clone().subtract(1, 'day'); RECENT_DAYS.length < 3; d.subtract(1, 'day')) {
        if (d.day() != 0) { RECENT_DAYS.push(dayStr(d)); }
    }
    const runsOn = (batch, day) => day >= dayStr(startDay(batch)) && day <= dayStr(lastClassDay(batch));
    // today's class number in a batch: class days from its start, Sundays not counted
    const classDayOf = start => { let n = 0; for (let d = moment(start).startOf('day'); !d.isAfter(today, 'day'); d.add(1, 'day')) { if (d.day() != 0) { n++; } } return n; };
    // a class counts as marked when its batch has a session that day, held or not
    const sessionsOn = days => _.keyBy(params.db.objects('Session').filtered('voided = false AND (' + days.map((d, n) => 'scheduledDate == $' + n).join(' OR ') + ')', ...days),
        s => s.groupSubjectUUID + '|' + s.scheduledDate);
    const unmarkedDays = (batch, marked, days) => days.filter(day => runsOn(batch, day) && !marked[batch.uuid + '|' + day]);

    const marked = sessionsOn(RECENT_DAYS);
    return params.db.objects('Individual').filtered('voided = false AND subjectType.group = true')
        .filter(batch => _.has(BATCH_DAYS, batch.subjectType.name) && inPlace(batch) && unmarkedDays(batch, marked, RECENT_DAYS).length > 0);
};

'use strict';
({params, imports}) => {
    // People whose health follow-up in the last 90 days says the referral was not followed; a tap opens each person.
    const moment = imports.moment;
    const _ = imports.lodash;
    const CONCEPT_FOLLOWED_REFERRAL_UUID = "189e6d4b-dad4-5467-aa81-5003b10cf409";
    const CONCEPT_NO_UUID = "fa43440e-cedd-503c-881b-c37d2100f00f";
    const since = moment().startOf('day').subtract(90, 'days');
    const addressFilter = _.find(params.ruleInput || [], filter => filter.type == 'Address');
    const places = addressFilter && addressFilter.filterValue && addressFilter.filterValue.length ? _.map(addressFilter.filterValue, 'uuid') : [];

    if (params.db.isSqlite) {
        // new database: the count is one SQL query and the list loads only when the card is tapped
        const where = ' FROM encounter e JOIN individual i ON i.uuid = e.individual_uuid'
            + " WHERE +e.voided = 0 AND +i.voided = 0 AND e.encounter_type_uuid IN (SELECT uuid FROM encounter_type WHERE name = 'Health Follow-up')"
            + " AND e.encounter_date_time >= ? AND (SELECT json_extract(json_extract(o.value, '$.valueJSON'), '$.answer') FROM json_each(e.observations) o"
            + " WHERE json_extract(o.value, '$.concept.uuid') = ?) = ?"
            + (places.length ? ' AND i.lowest_address_level_uuid IN (' + places.map(() => '?').join(',') + ')' : '');
        const values = [since.valueOf(), CONCEPT_FOLLOWED_REFERRAL_UUID, CONCEPT_NO_UUID].concat(places);
        return params.db.execReport('SELECT COUNT(DISTINCT i.uuid)' + where, values, 'SELECT DISTINCT i.uuid' + where, values, 'Individual');
    }

    const inPlace = subject => !places.length || (!!subject.lowestAddressLevel && _.includes(places, subject.lowestAddressLevel.uuid));
    const people = params.db.objects('Encounter')
        .filtered("voided = false AND encounterType.name = 'Health Follow-up' AND encounterDateTime >= $0", since.toDate())
        .filter(enc => !enc.individual.voided && inPlace(enc.individual) && enc.getObservationValue(CONCEPT_FOLLOWED_REFERRAL_UUID) == CONCEPT_NO_UUID)
        .map(enc => enc.individual);
    return _.uniqBy(people, 'uuid');
};

'use strict';
({params, imports}) => {
    if (params.db.isSqlite) {
        // New database (SQLite): the counting is done in SQL, so the phone loads no records for the tile.
        const moment = imports.moment;
        const _ = imports.lodash;
        const db = params.db;
        const today = moment().startOf('day');
        const todayStart = today.valueOf();
        const todayEnd = today.clone().endOf('day').valueOf();
        // dates are stored as epoch milliseconds; this shifts them to the phone's own day for date() in SQL
        const tz = (moment().utcOffset() >= 0 ? '+' : '') + moment().utcOffset() + ' minutes';
        const BATCH_DAYS = {"Summer Camp": 5, "Beautician Skill Training": 90, "Career Guidance and Development Program": 15, "CSL (STEM Lab)": 365, "Sewing (SST)": 90, "Computer (CST)": 90, "EV (TST-EV)": 90, "Solar (TST-Solar)": 90, "Candle and Diya (CMT)": 5, "Chocolate (CMT)": 3, "Jewellery (JMT)": 5, "Financial (FLP)": 5, "Entrepreneurship (EDT)": 10, "Asani (ADT)": 1};
        const GRACE_DAYS = 15;
        const DAY = 86400000;
        const clean = text => String(text || '').replace(/[<>&"']/g, '');
        const addressFilter = _.find(params.ruleInput || [], filter => filter.type == 'Address');
        const places = addressFilter && addressFilter.filterValue && addressFilter.filterValue.length ? _.map(addressFilter.filterValue, 'uuid') : [];
        // the village filter as SQL: the picked places and every place under them
        const inPlace = alias => places.length ? ' AND ' + alias + '.lowest_address_level_uuid IN (' + places.map(() => '?').join(',') + ')' : '';
        const quote = text => "'" + String(text).replace(/'/g, "''") + "'";
        const daysCase = stAlias => 'CASE ' + stAlias + '.name ' + _.map(BATCH_DAYS, (days, name) => 'WHEN ' + quote(name) + ' THEN ' + days).join(' ') + ' ELSE 30 END';
        const answerOf = col => "json_extract(json_extract(" + col + ", '$.valueJSON'), '$.answer')";
        const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";
        const CONCEPT_BATCH_LAST_CLASS_DAY_UUID = "476c6430-95f7-5efa-8a34-8cedf9011e3b";
        // a date answer (stored as an ISO text) as epoch milliseconds
        const dateObs = (alias, concept) => '(SELECT CAST(ROUND((julianday(' + answerOf('o.value') + ') - 2440587.5) * 86400000) AS INTEGER) FROM json_each(' + alias
            + ".observations) o WHERE json_extract(o.value, '$.concept.uuid') = " + quote(concept) + ')';
        // a batch's start: its Start date, or the registration date for an older batch
        const startOf = alias => 'COALESCE(' + dateObs(alias, CONCEPT_BATCH_START_DATE_UUID) + ', ' + alias + '.registration_date)';
        // a batch's last class day: its Last class day, or N class days from the start with Sundays skipped
        const lastDay = (alias, stAlias) => 'COALESCE(' + dateObs(alias, CONCEPT_BATCH_LAST_CLASS_DAY_UUID) + ', ' + startOf(alias) + ' + ((' + daysCase(stAlias) + ') - 1 + '
            + "(((CAST(strftime('%w', " + startOf(alias) + " / 1000, 'unixepoch', '" + tz + "') AS INTEGER) + 6) % 7 + (" + daysCase(stAlias) + ') - 1) / 6)) * ' + DAY + ')';
        // Avni Attendance (13 Nov): a class counts as marked when its batch has a session that day, held or not
        const dayStr = ms => moment(ms).format('YYYY-MM-DD');
        const TODAY = dayStr(today);
        const isClassDay = today.day() != 0;
        // the last 3 class days before today; Sunday is off
        const RECENT_DAYS = [];
        for (let d = today.clone().subtract(1, 'day'); RECENT_DAYS.length < 3; d.subtract(1, 'day')) {
            if (d.day() != 0) { RECENT_DAYS.push(dayStr(d)); }
        }
        // every batch in the village filter with its start and last class day (epoch ms); start <= ? and last + grace >= ? keep the current ones
        const batchRows = (where, values) => db.execQuery("SELECT b.uuid, b.first_name AS name, st.name AS type, COALESCE(al.name, '-') AS village, "
            + startOf('b') + ' AS start, ' + lastDay('b', 'st') + ' AS last FROM individual b JOIN subject_type st ON st.uuid = b.subject_type_uuid'
            + ' LEFT JOIN address_level al ON al.uuid = b.lowest_address_level_uuid WHERE +b.voided = 0 AND st."group" = 1' + (where || '') + inPlace('b'),
            (values || []).concat(places));
        const runsOn = (b, day) => day >= dayStr(b.start) && day <= dayStr(b.last);
        // today's class number in a batch: class days from its start, Sundays not counted
        const classDayOf = start => { let n = 0; for (let d = moment(start).startOf('day'); !d.isAfter(today, 'day'); d.add(1, 'day')) { if (d.day() != 0) { n++; } } return n; };
        const sessionsOn = days => _.keyBy(db.execQuery('SELECT group_subject_uuid AS batch, scheduled_date AS day, status FROM session WHERE +voided = 0 AND scheduled_date IN ('
            + days.map(() => '?').join(',') + ')', days), s => s.batch + '|' + s.day);
        const unmarkedDays = (b, marked, days) => days.filter(day => runsOn(b, day) && !marked[b.uuid + '|' + day]);
        // one question's answer on a row, read from its observations JSON
        const obsValue = (alias, concept) => '(SELECT ' + answerOf('o.value') + ' FROM json_each(' + alias + ".observations) o WHERE json_extract(o.value, '$.concept.uuid') = " + quote(concept) + ')';
        const obsName = (alias, concept) => '(SELECT c.name FROM json_each(' + alias + '.observations) o JOIN concept c ON c.uuid = ' + answerOf('o.value')
            + " WHERE json_extract(o.value, '$.concept.uuid') = " + quote(concept) + ')';
        const typeIs = (alias, names) => alias + '.encounter_type_uuid IN (SELECT uuid FROM encounter_type WHERE name IN (' + [].concat(names).map(quote).join(', ') + '))';
        // a list card's answer from a list of person or batch ids
        const listOf = ids => {
            const sql = ' FROM individual WHERE uuid IN (' + ids.map(() => '?').join(',') + ')';
            return db.execReport('SELECT COUNT(*)' + sql, ids, 'SELECT uuid' + sql, ids, 'Individual');
        };
        const CONCEPT_EVENT_STATUS_UUID = "622693a9-5f1f-56f4-97a1-d3f99f5b6969";
        const CONCEPT_DRAFT_UUID = "6aa53622-438a-51ed-95fe-e905af14bdd8";
        const where = ' FROM individual i JOIN subject_type st ON st.uuid = i.subject_type_uuid'
            + " WHERE +i.voided = 0 AND st.name = 'Event Matrix' AND i.registration_date < ? AND " + obsValue('i', CONCEPT_EVENT_STATUS_UUID) + ' = ?' + inPlace('i');
        const values = [today.clone().subtract(7, 'days').valueOf(), CONCEPT_DRAFT_UUID].concat(places);
        return db.execReport('SELECT COUNT(*)' + where, values, 'SELECT i.uuid' + where, values, 'Individual');
    }
    // Events left in Draft for more than 7 days: they are not in the donor numbers until submitted.
    const moment = imports.moment;
    const _ = imports.lodash;
    const CONCEPT_EVENT_STATUS_UUID = "622693a9-5f1f-56f4-97a1-d3f99f5b6969";
    const CONCEPT_DRAFT_UUID = "6aa53622-438a-51ed-95fe-e905af14bdd8";
    const weekAgo = moment().startOf('day').subtract(7, 'days');

    const addressFilter = _.find(params.ruleInput || [], filter => filter.type == 'Address');
    const places = addressFilter && addressFilter.filterValue && addressFilter.filterValue.length ? _.map(addressFilter.filterValue, 'uuid') : null;
    const inPlace = subject => !places || (!!subject.lowestAddressLevel && _.includes(places, subject.lowestAddressLevel.uuid));

    return params.db.objects('Individual')
        .filtered("voided = false AND subjectType.name = 'Event Matrix' AND registrationDate < $0", weekAgo.toDate())
        .filter(event => inPlace(event) && event.getObservationValue(CONCEPT_EVENT_STATUS_UUID) == CONCEPT_DRAFT_UUID);
};

'use strict';
({params, imports}) => {
    const _ = imports.lodash;

    // the dashboard's village filter hands over the picked places and every place under them
    const addressFilter = _.find(params.ruleInput || [], filter => filter.type == 'Address');
    const places = addressFilter && addressFilter.filterValue && addressFilter.filterValue.length ? _.map(addressFilter.filterValue, 'uuid') : null;
    const inPlace = subject => !places || (!!subject.lowestAddressLevel && _.includes(places, subject.lowestAddressLevel.uuid));

    const people = params.db.objects('Individual').filtered('voided = false AND subjectType.name = $0', "Beneficiary").filter(inPlace);
    const key = person => _.toLower(_.trim(person.firstName)) + '|' + _.toLower(_.trim(person.lastName)) + '|' + (person.lowestAddressLevel ? person.lowestAddressLevel.uuid : '');
    return _.flatten(_.values(_.groupBy(people, key)).filter(sameName => sameName.length > 1));
};

