formElements.rule:
'use strict';
({params, imports}) => {
    const individual = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    let answersToShow = [];
    let questionGroupIndex = params.questionGroupIndex;
    const PROGRAMS_BY_PILLAR = {
        "Health": ["Gynec Checkup & Awareness Camp", "Asani Sanitary Napkin-Users", "Cancer Checkup & Awareness Camp", "General Health Checkup & Awareness Camp", "Health & Hygiene Awareness", "Bal Health Mela", "Menstrual Hygiene Management Awareness Camp", "Primary Health & Hygiene Education", "Vision Care and Awareness Camp", "Asani Free Distribution", "Emergency Aid"],
        "Livelihood": ["Sewing Skill Training", "Asani Distribution Training", "Asani Distributors", "Asani Production", "Beautician Skill Training", "Candle & Diya Making Training", "Jewellery Making Training", "Chocolate Making Training", "Entrepreneurship Development Training", "Computer Skill Training", "Technical Skill Training", "Help Desk", "Financial Literacy Program", "Vocational Skill Training", "Entrepreneurship Awareness", "Emergency Aid"],
        "Education": ["Summer Camp", "Creative STEM Lab", "Entrepreneurship Awareness", "Career Guidance and Development Program", "Emergency Aid"]
    };
    const CONCEPT_DETAILS_OF_THE_PROGRAM_UUID = "1d3d3ef7-6111-5dd2-9321-a6484b18a259";
    const CONCEPT_PROGRAM_CATEGORY_UUID = "9965e87b-c666-5a8c-89b9-b86123c8d4fd";
    const CONCEPT_PROGRAM_NAME_UUID = "da8fbedb-c464-5163-9130-8ce61f89832f";

    const programDetails = individual.findObservation(CONCEPT_DETAILS_OF_THE_PROGRAM_UUID);
    const programRows = programDetails ? programDetails.getValueWrapper().repeatableObservations || [programDetails.getValueWrapper()] : [];
    const programRow = programRows[questionGroupIndex];
    const categoryObservation = programRow ? programRow.findObservationByConceptUUID(CONCEPT_PROGRAM_CATEGORY_UUID) : null;
    const category = categoryObservation ? categoryObservation.getReadableValue() : null;
    const chosenElsewhere = programRows.filter((row, index) => index != questionGroupIndex).map(row => row.findObservationByConceptUUID(CONCEPT_PROGRAM_NAME_UUID)).filter(observation => observation).map(observation => observation.getReadableValue());

    answersToShow = _.difference(PROGRAMS_BY_PILLAR[category] || [], chosenElsewhere);
    const ownObservation = programRow ? programRow.findObservationByConceptUUID(CONCEPT_PROGRAM_NAME_UUID) : null;
    const picked = ownObservation ? ownObservation.getReadableValue() : null;
    if (picked && chosenElsewhere.includes(picked)) {
        validationErrors.push("This programme is already in another row");
    }
    if (picked && category && !(PROGRAMS_BY_PILLAR[category] || []).includes(picked)) {
        validationErrors.push("Pick a programme from the chosen category");
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors, answersToShow);
};

forms.decisionRule:
"use strict";
({params, imports}) => {
    const plan = params.entity;
    const decisions = params.decisions;
    const moment = imports.moment;

    const start = moment(plan.registrationDate);
    const firstYear = start.month() >= 3 ? start.year() : start.year() - 1;
    const prefix = 'Annual Plan FY ' + firstYear + '-' + String(firstYear + 1).slice(2);
    const typed = (plan.firstName || '').trim();
    const ownText = typed.indexOf('Annual Plan FY ') == 0 ? typed.split(' - ').slice(1).join(' - ') : typed;
    const name = prefix + (ownText ? ' - ' + ownText : '');
    if (name != typed && typeof plan.setFirstName == 'function') {
