    const marked = _.union(absentStudents || [], presentStudents || []);
    const unmarked = members.filter(groupSubject => !_.includes(marked, groupSubject.memberSubject.uuid));

    if (members.length > 0 && unmarked.length > 0) {
        validationErrors.push("Mark every student as present or absent. Not marked: " + unmarked.length);
    }
    if (marked.length == 0) {
        validationErrors.push("Mark at least one student. Add students to the batch first if it is empty");
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

