'use strict';
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_CAMP_TYPE_UUID = "6c212c05-3ce5-5c0b-8ac2-8fd70dfbd44a";
    const CONCEPT_GYNEC_UUID = "82c28d58-c4a0-539c-8aca-45b1fd6ef536";
    const CONCEPT_PEDIATRIC_UUID = "920d0fea-cfc7-527c-8655-f1fbf528a670";
    const CONCEPT_BAL_HEALTH_MELA_UUID = "3adfcd79-aa8b-541f-a737-4836e59c8c7a";

    const campType = encounter.getObservationValue(CONCEPT_CAMP_TYPE_UUID);

    const person = encounter.individual;
    const isMale = !!person.gender && person.gender.name == 'Male';
    const age = person.getAgeInYears();
    const notForThisPerson = (isMale ? [CONCEPT_GYNEC_UUID] : []).concat(age >= 18 ? [CONCEPT_PEDIATRIC_UUID, CONCEPT_BAL_HEALTH_MELA_UUID] : []);
    // a retired answer (voided, 19 Nov) has no answer object on the form: skip it, or the phone crashes
    answersToSkip = notForThisPerson.map(answerUuid => formElement.getAnswerWithConceptUuid(answerUuid)).filter(answer => !!answer);

    if (campType && _.includes(notForThisPerson, campType)) {
        validationErrors.push("This camp is not for this person. Gynec is for women; Pediatric and Bal Health Mela are for children");
    }

    // the same type twice for one person on one day is a double entry (G11)
    const sameDayEntry = _.find(person.getEncounters(true), enc => enc.encounterType.name == encounter.encounterType.name && enc.encounterDateTime && enc.uuid != encounter.uuid
        && moment(enc.encounterDateTime).isSame(encounter.encounterDateTime, 'day') && enc.getObservationValue(CONCEPT_CAMP_TYPE_UUID) == campType);
    if (campType && sameDayEntry) {
        validationErrors.push("This person already has this entry for " + moment(encounter.encounterDateTime).format("DD-MM-YYYY") + ". Open that entry and use Edit");
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

