'use strict';
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_TOKEN_NUMBER_UUID = "12069e39-f76b-58a6-9725-81c312d6f1a7";

    const tokenNumber = encounter.getObservationValue(CONCEPT_TOKEN_NUMBER_UUID);

    if (!_.isFinite(tokenNumber) && moment(encounter.encounterDateTime || undefined).isSame(moment(), 'day')) {
        try {
            const from = moment().startOf('day').format('YYYY-MM-DD@HH:mm:ss');
            const campType = encounter.encounterType.name;
            const people = params.services.individualService.getSubjects(encounter.individual.subjectType.name,
                "SUBQUERY(encounters, $e, $e.voided = false AND $e.encounterType.name = '" + campType + "' AND $e.encounterDateTime >= " + from + ").@count > 0");
            let highest = 0;
            people.forEach(person => person.getEncounters(false).forEach(enc => {
                if (enc.uuid != encounter.uuid && enc.encounterType.name == campType && enc.encounterDateTime && moment(enc.encounterDateTime).isSame(moment(), 'day')) {
                    const token = enc.getObservationValue(CONCEPT_TOKEN_NUMBER_UUID);
                    if (_.isFinite(token) && token > highest) {
                        highest = token;
                    }
                }
            }));
            value = highest + 1;
        } catch (lookupNotSupported) {
        }
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

