    const onlyTheFill = typed.indexOf(course + ' - ') == 0 && typed.split(' - ').slice(2).join(' - ').trim() == '';
    if ((!typed.trim() || onlyTheFill) && typeof individual.setFirstName == 'function') {
        individual.setFirstName(course + ' - ' + month + ' - ');
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

