    const CONCEPT_YES_UUID = "3cdf914c-07ec-5314-bb49-df046a3e0a97";

    const alreadyScheduled = _.find(encounter.individual.getEncounters(true), enc => enc.encounterType.name == encounterType && !enc.encounterDateTime && enc.uuid != encounter.uuid);
    const decidingAnswer = encounter.getObservationValue(CONCEPT_SELECTED_FOR_TRAINING_UUID);

    if (decidingAnswer == CONCEPT_YES_UUID && !alreadyScheduled) {
        const baseDate = moment(encounter.encounterDateTime);
        scheduleBuilder.add({
            name: encounterType,
            encounterType: encounterType,
            earliestDate: baseDate.clone().add(0, 'days').startOf('day').toDate(),
            maxDate: baseDate.clone().add(7, 'days').endOf('day').toDate()
        });
    }

    return scheduleBuilder.getAll();
};

