"use strict";
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const _ = imports.lodash;
    const scheduleBuilder = new imports.rulesConfig.VisitScheduleBuilder({encounter});
    const encounterType = "Livelihood Follow-up";
    const maximumVisits = 2;
    const CONCEPT_REASON_FOR_CANCELLATION_UUID = "27da8209-5016-50e0-a51f-2d24eb804e8c";
    const CONCEPT_PERSON_MOVED_AWAY_UUID = "33bf832a-2cd9-564d-a49e-0b9a1772c0d4";
    const CONCEPT_PERSON_DIED_UUID = "79906634-6557-56c2-a8b5-51b39508a4a5";
    const CONCEPT_PERSON_REFUSED_UUID = "07b99e5a-4c82-59bf-8a40-4d98e9cc4e2a";

    const cancelReason = encounter.findCancelEncounterObservation(CONCEPT_REASON_FOR_CANCELLATION_UUID);
    const personLeft = !!cancelReason && [CONCEPT_PERSON_MOVED_AWAY_UUID, CONCEPT_PERSON_DIED_UUID, CONCEPT_PERSON_REFUSED_UUID].includes(cancelReason.getValue());
    const lastStart = _.find(encounter.individual.getEncounters(true), enc => enc.encounterType.name == 'Endline / Post-test' && enc.encounterDateTime);
    const seriesStart = lastStart ? lastStart.encounterDateTime : new Date(0);
    const earlierVisits = encounter.individual.getEncounters(false).filter(enc => enc.encounterType.name == encounterType && enc.uuid != encounter.uuid
        && (enc.encounterDateTime >= seriesStart || enc.cancelDateTime >= seriesStart));
    const visitsDone = earlierVisits.length + 1;
    const alreadyScheduled = _.find(encounter.individual.getEncounters(true), enc => enc.encounterType.name == encounterType && !enc.encounterDateTime && enc.uuid != encounter.uuid);

    if (visitsDone < maximumVisits && !alreadyScheduled && !personLeft) {
        const baseDate = moment(encounter.cancelDateTime);
        scheduleBuilder.add({
            name: encounterType,
            encounterType: encounterType,
            earliestDate: baseDate.clone().add(30, 'days').toDate(),
            maxDate: baseDate.clone().add(45, 'days').toDate()
        });
    }

    return scheduleBuilder.getAll();
};

