forms.visitScheduleRule:
"use strict";
({params, imports}) => {
    const encounter = params.entity;
    const moment = imports.moment;
    const _ = imports.lodash;
    const scheduleBuilder = new imports.rulesConfig.VisitScheduleBuilder({encounter});
    const encounterType = "Health Follow-up";
    const CONCEPT_FOLLOW_UP_NEEDED_UUID = "b5cf7960-352b-5309-b6f7-53c3645444c9";
    const CONCEPT_YES_UUID = "3cdf914c-07ec-5314-bb49-df046a3e0a97";

    const alreadyScheduled = _.find(encounter.individual.getEncounters(true), enc => enc.encounterType.name == encounterType && !enc.encounterDateTime && enc.uuid != encounter.uuid);
    const decidingAnswer = encounter.getObservationValue(CONCEPT_FOLLOW_UP_NEEDED_UUID);

    if (decidingAnswer == CONCEPT_YES_UUID && !alreadyScheduled) {
        const baseDate = moment(encounter.encounterDateTime);
        scheduleBuilder.add({
            name: encounterType,
            encounterType: encounterType,
            earliestDate: baseDate.clone().add(30, 'days').startOf('day').toDate(),
            maxDate: baseDate.clone().add(45, 'days').endOf('day').toDate()
        });
    }

    return scheduleBuilder.getAll();
};

