'use strict';
({params, imports}) => {
    const individual = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_BATCH_LAST_CLASS_DAY_UUID = "476c6430-95f7-5efa-8a34-8cedf9011e3b";
    const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";

    const batchLastClassDay = individual.getObservationValue(CONCEPT_BATCH_LAST_CLASS_DAY_UUID);
    const batchStartDate = individual.getObservationValue(CONCEPT_BATCH_START_DATE_UUID);

    const BATCH_DAYS = {
        "Summer Camp": 5,
        "Beautician Skill Training": 90,
        "Career Guidance and Development Program": 15,
        "CSL (STEM Lab)": 365,
        "Sewing (SST)": 90,
        "Computer (CST)": 90,
        "EV (TST-EV)": 90,
        "Solar (TST-Solar)": 90,
        "Candle and Diya (CMT)": 5,
        "Chocolate (CMT)": 3,
        "Jewellery (JMT)": 5,
        "Financial (FLP)": 5,
        "Entrepreneurship (EDT)": 10,
        "Asani (ADT)": 1
    };

    const begin = moment(batchStartDate || individual.registrationDate).startOf('day');
    const days = BATCH_DAYS[individual.subjectType.name] || 30;
    const mondayFirst = (begin.day() + 6) % 7;
    if (!batchLastClassDay) {
        value = begin.clone().add(days - 1 + Math.floor((mondayFirst + days - 1) / 6), 'days').toDate();
    }
    if (batchLastClassDay && moment(batchLastClassDay).isBefore(begin, 'day')) {
        validationErrors.push("Last class day cannot be before the start date");
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

'use strict';
({params, imports}) => {
    const individual = params.entity;
    const moment = imports.moment;
    const formElement = params.formElement;
    const _ = imports.lodash;
    let visibility = true;
    let value = null;
    let answersToSkip = [];
    let validationErrors = [];
    const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";

    const batchStartDate = individual.getObservationValue(CONCEPT_BATCH_START_DATE_UUID);

    const month = moment(batchStartDate || individual.registrationDate).format('MMM YYYY');
    value = month;

    // the rule runs when the page opens, on the record itself, so the name box shows this at once
    const course = individual.subjectType.name;
    const typed = individual.firstName || '';
    const onlyTheFill = typed.indexOf(course + ' - ') == 0 && typed.split(' - ').slice(2).join(' - ').trim() == '';
    if ((!typed.trim() || onlyTheFill) && typeof individual.setFirstName == 'function') {
        individual.setFirstName(course + ' - ' + month + ' - ');
    }

    return new imports.rulesConfig.FormElementStatus(formElement.uuid, visibility, value, answersToSkip, validationErrors);
};

forms.decisionRule:
"use strict";
({params, imports}) => {
    const batch = params.entity;
    const decisions = params.decisions;
    const moment = imports.moment;
    const CONCEPT_BATCH_START_DATE_UUID = "bbb27b31-b392-54c5-8984-4bd35b51af4f";

    const course = batch.subjectType.name;
    const typed = (batch.firstName || '').trim();
    const ownText = typed.indexOf(course + ' - ') == 0 ? typed.split(' - ').slice(2).join(' - ') : typed;
    const start = batch.getObservationValue(CONCEPT_BATCH_START_DATE_UUID) || batch.registrationDate;
    const name = course + ' - ' + moment(start).format('MMM YYYY') + (ownText ? ' - ' + ownText : '');
    if (name != typed && typeof batch.setFirstName == 'function') {
        batch.setFirstName(name);
    }

    return decisions;
};

